import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, ToolCallInput } from 'claude-code'

import {
  applyMaskedEdit,
  bashTouchesSecret,
  ensureGitignore,
  findEnvValue,
  hideBlocks,
  looksLikeKey,
  looksLikeToken,
  maskBlocks,
  maskable,
  parseEnv,
  sanitizeName,
  touchesSecret,
  upsertEnv,
} from './lib'

const PANE = 'cofre-chaves'
const nome = atom({ plugin: 'cofre-chaves', key: 'nome' } as const, '')
const tokenLen = atom({ plugin: 'cofre-chaves', key: 'tokenLen' } as const, 0)
const aviso = atom({ plugin: 'cofre-chaves', key: 'aviso' } as const, '')
const nomes = atom({ plugin: 'cofre-chaves', key: 'nomes' } as const, [])

const GUIDANCE =
  'Chaves ficam no .env, salvas pelo usuário com /chave. Nunca peça para colar no chat; ' +
  'referencie pelo nome. Scripts carregam o .env sozinhos (ex.: dotenv).'

// O valor real do token vive só aqui: nunca num atom, nunca na UI.
let token = ''

async function loadEnv($: EngineInterface): Promise<Map<string, string>> {
  try {
    return parseEnv(await $.fs.read(`${await $.session.root()}/.env`))
  } catch {
    return new Map()
  }
}

async function refreshNames($: EngineInterface) {
  const names = [...(await loadEnv($)).keys()]
  await update($, nomes, () => names)
}

async function readOr($: EngineInterface, path: string): Promise<string> {
  try {
    return await $.fs.read(path)
  } catch {
    return ''
  }
}

async function saveKey($: EngineInterface) {
  const name = await read($, nome)
  if (name === '' || /^[0-9]/.test(name)) {
    await update($, aviso, () => 'Dê um nome que comece com letra ou _ (ex.: OPENAI_API_KEY).')
    return
  }
  if (token === '') {
    await update($, aviso, () => 'O token está vazio.')
    return
  }

  const root = await $.session.root()
  await $.fs.write(`${root}/.env`, upsertEnv(await readOr($, `${root}/.env`), name, token))
  token = ''

  let note = ''
  if (await $.fs.exists(`${root}/.git`)) {
    const ignored = ensureGitignore(await readOr($, `${root}/.gitignore`))
    if (ignored !== null) {
      await $.fs.write(`${root}/.gitignore`, ignored)
      note = ' (.env adicionado ao .gitignore)'
    }
  }

  await update($, tokenLen, () => 0)
  await update($, nome, () => '')
  await update($, aviso, () => `${name} salvo no .env${note}.`)
  await refreshNames($)
}

async function onNameInput($: EngineInterface, value: string) {
  if (looksLikeToken(value)) {
    token = value.trim()
    await update($, tokenLen, () => token.length)
    await update($, nome, () => '')
    await update($, aviso, () => 'Isso parece um token: movi para o campo Token. Agora dê um nome.')
    return
  }
  await update($, nome, () => sanitizeName(value))
}

async function onTokenInput($: EngineInterface, shown: string) {
  token = applyMaskedEdit(token, shown)
  await update($, tokenLen, () => token.length)
}

/** Por que a chamada toca num arquivo secreto, ou null. */
function blockedReason(e: ToolCallInput): string | null {
  const tool = String(e.tool)
  const args = e as unknown as Record<string, unknown>
  const str = (k: string) => (typeof args[k] === 'string' ? (args[k] as string) : '')

  if (tool === 'Read' || tool === 'Edit' || tool === 'Write') {
    if (touchesSecret(str('file_path'))) return `${tool} bloqueado: ${str('file_path')} é um arquivo secreto.`
  }
  if (tool === 'Grep') {
    for (const k of ['path', 'glob']) if (str(k) !== '' && touchesSecret(str(k))) return `Grep bloqueado: ${str(k)} alcança arquivo secreto.`
  }
  if (tool === 'Bash' && bashTouchesSecret(str('command'))) {
    return 'Comando bloqueado: ele toca num arquivo secreto. Carregar o .env (source .env, --env-file) é permitido.'
  }

  return null
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'chave', description: 'Salva uma chave no .env do projeto sem passar pelo chat' })
    await refreshNames($)

    return next(e)
  })

  on('command.run', { command: 'chave' }, async $ => {
    await refreshNames($)
    await update($, aviso, () => '')
    await $.ui.open({ id: PANE, title: 'Cofre de chaves', focus: true, closeOnEscape: true })

    return { text: 'Cofre de chaves aberto.' }
  })

  // 2. arquivos secretos
  on('tool.call', ($, e, next) => {
    const why = blockedReason(e)
    if (why !== null) return { deny: `${why} Use a variável pelo nome; scripts carregam o .env sozinhos.` }

    return next(e)
  }).catch(($, e, next) => (next.called ? next(e) : { deny: 'cofre-chaves não conseguiu verificar esta chamada.' }))

  // 3. chave colada no prompt
  on('prompt.submit', async ($, e, next) => {
    const kind = looksLikeKey(e.text)
    const envName = kind === null ? findEnvValue(e.text, await loadEnv($)) : null
    if (kind !== null || envName !== null) {
      const what = kind ?? `valor de ${envName} no .env`

      return { drop: `Esse prompt contém uma chave (${what}). Não cole chaves no chat: use /chave.` }
    }

    return next(e)
  }).catch(($, e, next) => (next.called ? next(e) : { drop: 'cofre-chaves não conseguiu verificar o prompt: use /chave para chaves.' }))

  // 4. saída de ferramenta: valores do .env viram [NOME]
  on('session.append', async ($, e, next) => {
    if (e.door !== 'tool-result' && e.door !== 'tool-message') return next(e)
    const env = await loadEnv($)
    if (maskable(env).length === 0) return next(e)

    return next({ ...e, message: { ...e.message, content: maskBlocks(e.message.content, env) } })
  }).catch(($, e, next) =>
    e.door === 'tool-result' || e.door === 'tool-message'
      ? next({ ...e, message: { ...e.message, content: hideBlocks(e.message.content) } })
      : next(e),
  )

  // 5. o modelo sabe onde ficam as chaves
  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    const names = [...(await loadEnv($)).keys()]
    const list = names.length > 0 ? `Variáveis salvas: ${names.join(', ')}.` : 'Nenhuma variável salva ainda.'

    return {
      ...composed,
      sections: [...composed.sections, { id: 'cofre-chaves:chaves', text: `${GUIDANCE}\n${list}`, scope: 'session' as const }],
    }
  })

  // 1. o painel
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const name = await read($, nome)
    const len = await read($, tokenLen)
    const note = await read($, aviso)
    const saved = await read($, nomes)

    if (e.surface === 'mobile') {
      const { Text } = $.ui.resolve(e)
      return <Text>Abra o /chave no terminal ou no desktop para digitar a chave.</Text>
    }
    const { Box, Input, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="column" gap={1}>
        <Input
          key="nome"
          label="Nome"
          placeholder="OPENAI_API_KEY"
          value={name}
          autoFocus
          onInput={value => void onNameInput($, value)}
          onSubmit={async value => {
            await onNameInput($, value)
            if (token !== '') await saveKey($)
          }}
        />
        <Input
          key="token"
          label="Token"
          placeholder="cole aqui"
          value={'•'.repeat(len)}
          submitLabel="salvar"
          onInput={value => void onTokenInput($, value)}
          onSubmit={async value => {
            await onTokenInput($, value)
            await saveKey($)
          }}
        />
        {note !== '' && (
          <Text color="warning">
            {note}
          </Text>
        )}
        <Box flexDirection="column">
          <Text bold>Salvas no .env</Text>
          {saved.length === 0 ? (
            <Text dimColor>nenhuma ainda</Text>
          ) : (
            saved.map(n => <Text>• {n}</Text>)
          )}
        </Box>
      </Box>
    )
  })
}

