// Regras puras do cofre: sem `$`, testáveis isoladamente.

// ---------- arquivos secretos ----------

const SAFE_ENV_SUFFIXES = ['.example', '.sample', '.template']
const SECRET_EXTENSIONS = ['.pem', '.key', '.p12', '.pfx']
const SSH_KEYS = ['id_rsa', 'id_ed25519', 'id_ecdsa']

/** Amostras usadas para saber se um glob alcança algum arquivo secreto. */
const SECRET_SAMPLES = ['.env', '.env.local', '.env.production', 'cert.pem', 'server.key', 'cert.p12', 'cert.pfx', ...SSH_KEYS]

function basename(path: string): string {
  const parts = path.replace(/\/+$/, '').split('/')

  return parts[parts.length - 1] ?? ''
}

/** .env, .env.* (menos .example/.sample/.template), *.pem, *.key, *.p12, *.pfx e chaves SSH. */
export function isSecretPath(path: string): boolean {
  const name = basename(path.trim())
  if (name === '.env') return true
  if (name.startsWith('.env.')) return !SAFE_ENV_SUFFIXES.some(s => name.endsWith(s))
  if (SSH_KEYS.includes(name)) return true

  return SECRET_EXTENSIONS.some(ext => name.length > ext.length && name.toLowerCase().endsWith(ext))
}

function globToRegExp(glob: string): RegExp {
  let out = ''
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i]!
    if (c === '*') out += '[^/]*'
    else if (c === '?') out += '[^/]'
    else if (c === '{') out += '('
    else if (c === '}') out += ')'
    else if (c === ',') out += '|'
    else if (c === '[') {
      const end = glob.indexOf(']', i)
      if (end === -1) out += '\\['
      else {
        out += `[${glob.slice(i + 1, end).replace(/^!/, '^')}]`
        i = end
      }
    } else out += c.replace(/[.+^$()|\\]/g, '\\$&')
  }

  return new RegExp(`^${out}$`)
}

/** Um caminho ou glob ("*.pem", ".env*", "**\/.env") que alcança arquivo secreto. */
export function touchesSecret(pathOrGlob: string): boolean {
  if (isSecretPath(pathOrGlob)) return true
  const name = basename(pathOrGlob.trim())
  if (!/[*?[{]/.test(name)) return false
  try {
    // Só curingas ("*", "**", "?*") não nomeiam nada; e sem ponto inicial o shell não alcança arquivos ocultos.
    if (name.replace(/[*?[\]{},!\\]/g, '') === '') return false
    const re = globToRegExp(name)
    const reachesHidden = name.startsWith('.')

    return SECRET_SAMPLES.some(sample => (reachesHidden || !sample.startsWith('.')) && re.test(sample))
  } catch {
    return false
  }
}

const ENV_FILE = String.raw`(?:"[^"]*"|'[^']*'|[^\s;&|()<>]+)`
/** Carregar o .env é permitido: `source .env`, `. .env`, `--env-file .env`. */
const ALLOWED_LOADS = [
  new RegExp(String.raw`(^|[;&|(\s])(?:source|\.)\s+(${ENV_FILE})`, 'g'),
  new RegExp(String.raw`()--env-file(?:=|\s+)(${ENV_FILE})`, 'g'),
]

function isEnvFile(path: string): boolean {
  const name = basename(path.replace(/^["']|["']$/g, ''))

  return name === '.env' || name.startsWith('.env.')
}

/** Um comando de shell que lê, copia, escreve ou lista um arquivo secreto. */
export function bashTouchesSecret(command: string): boolean {
  let rest = command
  for (const re of ALLOWED_LOADS) {
    rest = rest.replace(re, (match, lead: string, file: string) => (isEnvFile(file) ? `${lead} ` : match))
  }
  const tokens = rest.split(/[\s;&|()<>`"'=]+/).filter(Boolean)

  return tokens.some(touchesSecret)
}

// ---------- chaves no texto ----------

const KEY_PATTERNS: readonly [string, RegExp][] = [
  ['chave da Anthropic', /sk-ant-[A-Za-z0-9_-]{20,}/],
  ['chave da OpenAI', /\bsk-(?:proj-)?[A-Za-z0-9_-]{20,}/],
  ['token do GitHub', /\bgh[pousr]_[A-Za-z0-9]{20,}/],
  ['token do GitHub', /\bgithub_pat_[A-Za-z0-9_]{20,}/],
  ['token da Meta', /\bEAA[A-Za-z0-9]{50,}/],
  ['chave da AWS', /\bAKIA[0-9A-Z]{16}\b/],
  ['chave do Google', /\bAIza[0-9A-Za-z_-]{35}/],
  ['token do Slack', /\bxox[baprs]-[A-Za-z0-9-]{10,}/],
  ['JWT', /\beyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\./],
  ['chave privada', /-----BEGIN (?:[A-Z]+ )*PRIVATE KEY-----/],
]

/** O tipo da primeira chave reconhecida no texto, ou null. */
export function looksLikeKey(text: string): string | null {
  for (const [kind, re] of KEY_PATTERNS) if (re.test(text)) return kind

  return null
}

/** Texto colado no campo Nome que na verdade é um token. */
export function looksLikeToken(text: string): boolean {
  const t = text.trim()

  return looksLikeKey(t) !== null || t.length > 40 || /^\d{6,}$/.test(t)
}

/** Nome de variável: maiúsculas, só A-Z, 0-9 e _. */
export function sanitizeName(text: string): string {
  return text.toUpperCase().replace(/[^A-Z0-9_]/g, '')
}

// ---------- .env ----------

const LINE = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/

function unquote(raw: string): string {
  const v = raw.trim()
  if (v.startsWith("'")) {
    const end = v.indexOf("'", 1)

    return end === -1 ? v.slice(1) : v.slice(1, end)
  }
  if (v.startsWith('"')) {
    let out = ''
    for (let i = 1; i < v.length; i++) {
      const c = v[i]!
      if (c === '\\' && i + 1 < v.length) {
        const n = v[++i]!
        out += n === 'n' ? '\n' : n
      } else if (c === '"') break
      else out += c
    }

    return out
  }

  return v.replace(/\s+#.*$/, '').trim()
}

/** NOME → valor, na ordem do arquivo; a última definição vence. */
export function parseEnv(text: string): Map<string, string> {
  const env = new Map<string, string>()
  for (const line of text.split(/\r?\n/)) {
    if (/^\s*#/.test(line)) continue
    const m = LINE.exec(line)
    if (m) env.set(m[1]!, unquote(m[2]!))
  }

  return env
}

/** Aspas simples quando o valor tem espaço, #, aspas, \ ou $. */
export function formatEnvValue(value: string): string {
  if (!/[\s#'"\\$]/.test(value)) return value
  if (!value.includes("'")) return `'${value}'`

  return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n')}"`
}

/** Troca a linha NOME=... ou acrescenta uma no fim. */
export function upsertEnv(text: string, name: string, value: string): string {
  const line = `${name}=${formatEnvValue(value)}`
  const lines = text === '' ? [] : text.replace(/\r?\n$/, '').split(/\r?\n/)
  let found = false
  const out = lines.map(l => {
    const m = LINE.exec(l)
    if (m && m[1] === name && !/^\s*#/.test(l)) {
      found = true

      return line
    }

    return l
  })
  if (!found) out.push(line)

  return `${out.join('\n')}\n`
}

/** Garante a linha .env no .gitignore; null quando já está lá. */
export function ensureGitignore(text: string): string | null {
  const has = text.split(/\r?\n/).some(l => ['.env', '/.env', '.env*', '/.env*', '*.env'].includes(l.trim()))
  if (has) return null
  const base = text === '' || text.endsWith('\n') ? text : `${text}\n`

  return `${base}.env\n`
}

/** Valores do .env com 8 caracteres ou mais, os mais longos primeiro. */
export function maskable(env: Map<string, string>): [string, string][] {
  return [...env.entries()].filter(([, v]) => v.length >= 8).sort((a, b) => b[1].length - a[1].length)
}

/** Troca cada valor do .env (8+ caracteres) por [NOME]. */
export function maskText(text: string, env: Map<string, string>): string {
  let out = text
  for (const [name, value] of maskable(env)) out = out.split(value).join(`[${name}]`)

  return out
}

/** O nome da variável do .env cujo valor aparece no texto, ou null. */
export function findEnvValue(text: string, env: Map<string, string>): string | null {
  for (const [name, value] of maskable(env)) if (text.includes(value)) return name

  return null
}

/**
 * O campo Token mostra só bolinhas: cada edição chega como as bolinhas que
 * sobraram mais o que foi digitado ou colado. Devolve o valor real novo.
 */
export function applyMaskedEdit(real: string, shown: string): string {
  let kept = 0
  while (kept < shown.length && shown[kept] === '•') kept++
  kept = Math.min(kept, real.length)

  return real.slice(0, kept) + shown.slice(kept).replace(/•/g, '')
}

type Block = { type: string; [field: string]: unknown }

function mapToolResult(block: Block, fn: (text: string) => string): Block {
  if (typeof block.content === 'string') return { ...block, content: fn(block.content) }
  if (Array.isArray(block.content)) {
    return {
      ...block,
      content: (block.content as Block[]).map(inner =>
        inner.type === 'text' && typeof inner.text === 'string' ? { ...inner, text: fn(inner.text) } : inner,
      ),
    }
  }

  return block
}

/** Os blocos de uma saída de ferramenta com os valores do .env trocados por [NOME]. */
export function maskBlocks(content: readonly Block[], env: Map<string, string>): Block[] {
  const fn = (text: string) => maskText(text, env)

  return content.map(block => {
    if (block.type === 'text' && typeof block.text === 'string') return { ...block, text: fn(block.text) }
    if (block.type === 'tool_result') return mapToolResult(block, fn)

    return block
  })
}

/** Quando o mascaramento falha, a saída inteira some em vez de vazar. */
export function hideBlocks(content: readonly Block[]): Block[] {
  const hidden = () => '[saída ocultada pelo cofre-chaves]'

  return content.map(block => {
    if (block.type === 'text') return { ...block, text: hidden() }
    if (block.type === 'tool_result') return { ...block, content: hidden() }

    return block
  })
}

